const fs = require('fs');
const dir = '/backups';
const prefix = 'rayuela_';
const suffix = '.sql.gz';
let estado = 'OK';
let detalle = 'Backup OK';
let archivo = null;
try {
  const files = fs.existsSync(dir) ? fs.readdirSync(dir).filter(f => f.startsWith(prefix) && f.endsWith(suffix)) : [];
  if (files.length === 0) {
    estado = 'FALLO';
    detalle = 'No se encontraron archivos de backup en /backups';
  } else {
    files.sort();
    const ultimo = files[files.length - 1];
    const stats = fs.statSync(dir + '/' + ultimo);
    if (!stats || stats.size === 0) {
      estado = 'FALLO';
      detalle = 'El backup ' + ultimo + ' esta vacio';
    } else {
      estado = 'OK';
      detalle = 'Backup OK: ' + ultimo + ' (' + stats.size + ' bytes)';
    }
    archivo = ultimo;
  }
} catch (e) {
  estado = 'FALLO';
  detalle = 'Error validando backups: ' + e.message;
}
return [{ json: { estado: estado, detalle: detalle, archivo: archivo } }];
